#include <bits/stdc++.h>
using namespace std;

// One recipe; the compiler stamps out a separate function per type.
template <class T>
T maxOf(T a, T b) {
    static int calls = 0;  // each instantiation owns its own counter
    ++calls;
    cout << "  " << typeid(T).name() << " version, call #" << calls << "\n";
    return a > b ? a : b;
}

int main() {
    int a = maxOf(3, 7);          // maxOf<int>
    cout << "maxOf(3, 7) = " << a << "\n";
    a = maxOf(2, 1);              // same function again, counter goes up
    cout << "maxOf(2, 1) = " << a << "\n";
    double d = maxOf(2.5, 1.5);   // maxOf<double>
    cout << "maxOf(2.5, 1.5) = " << d << "\n";
    long l = maxOf<long>(5, 9);   // explicit argument also instantiates
    cout << "maxOf<long>(5, 9) = " << l << "\n";
    // Different addresses prove they are separate functions
    int (*pi)(int, int) = maxOf<int>;
    double (*pd)(double, double) = maxOf<double>;
    cout << "int and double versions are distinct functions: "
         << ((void*)pi != (void*)pd ? "yes" : "no") << "\n";
}

#include <bits/stdc++.h>
using namespace std;

// In a real project this body would sit in a .cpp file and the
// header would only declare it. Explicit instantiation then
// makes the compiler emit the code for a closed set of types.
template <class T>
T square(T x) { return x * x; }

// Explicit instantiation definitions (normally in the .cpp file)
template int square<int>(int);
template double square<double>(double);

// In the header you would write:  extern template int square<int>(int);
// (An extern template declaration must come BEFORE the definition above in
// other files; it tells them "do not instantiate, the .cpp already did".)

int main() {
    cout << "square(12) = " << square(12) << "\n";
    cout << "square(1.5) = " << square(1.5) << "\n";
    // square<long> was never instantiated in this file: it would still
    // work here because the definition is visible. With the body hidden
    // in another .cpp it would be a link error.
    cout << "square<long>(100000) = " << square<long>(100000) << "\n";
}

#include <bits/stdc++.h>
using namespace std;

template <class T> const char* kind() {
    if constexpr (is_same_v<T, int>) return "int";
    else if constexpr (is_same_v<T, const int>) return "const int";
    else if constexpr (is_same_v<T, int&>) return "int&";
    else if constexpr (is_same_v<T, const int&>) return "const int&";
    else if constexpr (is_same_v<T, const int*>) return "const int*";
    else if constexpr (is_same_v<T, int*>) return "int*";
    else if constexpr (is_same_v<T, int[3]>) return "int[3]";
    else return "other";
}

template <class T> void byValue(T) { cout << "T      -> T = " << kind<T>() << "\n"; }
template <class T> void byRef(T&) { cout << "T&     -> T = " << kind<T>() << "\n"; }
template <class T> void fwd(T&&) { cout << "T&&    -> T = " << kind<T>() << "\n"; }

int main() {
    int x = 1;
    const int c = 2;
    int arr[3] = {1, 2, 3};
    cout << "by value, const int lvalue:\n";  byValue(c);     // const dropped
    cout << "by value, int[3]:\n";            byValue(arr);   // decays to int*
    cout << "T&, const int lvalue:\n";        byRef(c);       // const kept
    cout << "T&, int[3]:\n";                  byRef(arr);     // T = int[3]
    cout << "T&&, lvalue x:\n";               fwd(x);         // T = int&
    cout << "T&&, const lvalue:\n";           fwd(c);         // T = const int&
    cout << "T&&, rvalue 5:\n";               fwd(5);         // T = int
}

#include <bits/stdc++.h>
using namespace std;

void f(int)          { cout << "  non-template f(int)\n"; }
template <class T>
void f(T)            { cout << "  template f(T)\n"; }
template <class T>
void f(T*)           { cout << "  template f(T*) (more specialized)\n"; }

int main() {
    int i = 1;
    cout << "f('a'):\n";  f('a');   // template: exact match beats promotion char->int
    cout << "f(5):\n";    f(5);     // tie on conversions -> non-template wins
    cout << "f(&i):\n";   f(&i);    // f(T*) more specialized than f(T)
    cout << "f<>(5):\n";  f<>(5);   // empty <> forces templates only
    cout << "f(2.5):\n";  f(2.5);   // exact for T=double beats double->int conversion
}

#include <bits/stdc++.h>
using namespace std;

template <class T> struct Traits { static string name() { return "generic"; } };
// Full specialization: one exact type
template <> struct Traits<int> { static string name() { return "int (full)"; } };
// Partial specializations: patterns
template <class T> struct Traits<T*> { static string name() { return "pointer to " + Traits<T>::name(); } };
template <class T> struct Traits<vector<T>> { static string name() { return "vector of " + Traits<T>::name(); } };

// Functions: use overloads for patterns, not partial specialization
template <class T> string describe(T) { return "value"; }
template <class T> string describe(T*) { return "pointer"; }

int main() {
    cout << Traits<double>::name() << "\n";
    cout << Traits<int>::name() << "\n";
    cout << Traits<int*>::name() << "\n";
    cout << Traits<vector<int*>>::name() << "\n";
    int x = 0;
    cout << "describe(x)  = " << describe(x) << "\n";
    cout << "describe(&x) = " << describe(&x) << "\n";
}

#include <bits/stdc++.h>
using namespace std;

// Fold over + with an init value: works for an empty pack too
template <class... Ts> auto sum(Ts... args) { return (args + ... + 0); }

// Fold over &&: true for an empty pack
template <class... Ts> bool allPositive(Ts... args) { return ((args > 0) && ...); }

// Comma fold prints each argument
template <class... Ts> void printAll(const Ts&... args) {
    ((cout << args << ' '), ...);
    cout << "(" << sizeof...(Ts) << " args)\n";
}

int main() {
    cout << "sum(1,2,3,4) = " << sum(1, 2, 3, 4) << "\n";
    cout << "sum() = " << sum() << "\n";
    cout << "allPositive(1,2,3) = " << allPositive(1, 2, 3) << "\n";
    cout << "allPositive(1,-2,3) = " << allPositive(1, -2, 3) << "\n";
    cout << "allPositive() = " << allPositive() << "\n";
    printAll(1, "two", 3.5, 'c');
    // Pack expansion with a pattern: square each element into a vector
    auto squares = [](auto... xs) { return vector<long>{(long)(xs * xs)...}; };
    for (long v : squares(1, 2, 3, 4)) cout << v << ' ';
    cout << "\n";
}

#include <bits/stdc++.h>
using namespace std;

struct Widget {
    Widget(const string& s) { cout << "  Widget(const string&) copy of \"" << s << "\"\n"; }
    Widget(string&& s)      { cout << "  Widget(string&&) moved \"" << s << "\"\n"; }
};

// Forwarding reference + variadic pack: pass arguments on unchanged
template <class T, class... Args>
unique_ptr<T> make(Args&&... args) {
    return unique_ptr<T>(new T(std::forward<Args>(args)...));
}

// Without forward: the parameter is a named lvalue, so move is lost
template <class T, class Arg>
unique_ptr<T> makeBad(Arg&& arg) { return unique_ptr<T>(new T(arg)); }

int main() {
    string name = "alice";
    cout << "make with lvalue:\n";   auto a = make<Widget>(name);          // copy
    cout << "make with rvalue:\n";   auto b = make<Widget>(string("bob")); // move
    cout << "makeBad with rvalue:\n"; auto c = makeBad<Widget>(string("carol")); // copies!
    cout << "name still intact: " << name << "\n";
}

