// A trait is a class template: primary says false, specialization says true
template <class T> struct my_is_pointer : false_type {};
template <class T> struct my_is_pointer<T*> : true_type {};
template <class T> struct my_is_pointer<T* const> : true_type {};

// A transformation trait
template <class T> struct my_remove_const { using type = T; };
template <class T> struct my_remove_const<const T> { using type = T; };

struct Base {};
struct Derived : Base {};

int main() {
    cout << boolalpha;
    cout << "my_is_pointer<int*>   = " << my_is_pointer<int*>::value << "\n";
    cout << "my_is_pointer<int>    = " << my_is_pointer<int>::value << "\n";
    cout << "my_is_pointer<int* const> = " << my_is_pointer<int* const>::value << "\n";
    cout << "remove_const<const int> is int: "
         << is_same_v<my_remove_const<const int>::type, int> << "\n";
    cout << "is_base_of<Base, Derived> = " << is_base_of_v<Base, Derived> << "\n";
    cout << "is_integral<long> = " << is_integral_v<long> << "\n";
    cout << "is_trivially_copyable<string> = " << is_trivially_copyable_v<string> << "\n";
    cout << "decay<const int&> is int: " << is_same_v<decay_t<const int&>, int> << "\n";
    // Used for decisions at compile time
    cout << "string nothrow-movable (vector moves on grow): "
         << is_nothrow_move_constructible_v<string> << "\n";
}

#include <bits/stdc++.h>
using namespace std;

// SFINAE through the return type: dropped if c.size() is invalid
template <class T>
auto len(const T& c, int) -> decltype(c.size()) {
    cout << "  container overload: ";
    return c.size();
}

// Fallback, only viable if the first one was removed
template <class T>
size_t len(const T&, long) {
    cout << "  fallback overload: ";
    return 0;
}

// enable_if: deliberately remove a template for non-integers
template <class T, enable_if_t<is_integral_v<T>, int> = 0>
string kind(T) { return "integral"; }
template <class T, enable_if_t<is_floating_point_v<T>, int> = 0>
string kind(T) { return "floating"; }

int main() {
    vector<int> v{1, 2, 3};
    cout << "len(vector):\n"; cout << len(v, 0) << "\n";   // 3
    cout << "len(42):\n";     cout << len(42, 0) << "\n";  // size() invalid -> fallback
    cout << "kind(7)   = " << kind(7) << "\n";
    cout << "kind(2.5) = " << kind(2.5) << "\n";
    // kind("x") would not compile: every overload was removed
}

#include <bits/stdc++.h>
using namespace std;

// if constexpr: same interface, different body per type
template <class T>
string show(const T& x) {
    if constexpr (is_arithmetic_v<T>) return "number " + to_string(x);
    else if constexpr (is_convertible_v<T, string>) return "text " + string(x);
    else static_assert(is_arithmetic_v<T> || is_convertible_v<T, string>, "unsupported type");
}

// Concepts: the interface itself rejects types, overloads chosen by property
template <class T> concept Container = requires(T t) { t.size(); t.begin(); };

template <Container C> string sizeInfo(const C& c) { return "container of " + to_string(c.size()); }
template <class T> requires integral<T> string sizeInfo(T x) { return "integer " + to_string(x); }

// Legacy enable_if style, same idea
template <class T, enable_if_t<is_floating_point_v<T>, int> = 0>
string sizeInfo(T x) { return "float " + to_string(x); }

int main() {
    cout << show(42) << "\n";
    cout << show(3.5) << "\n";
    cout << show("hello") << "\n";
    cout << sizeInfo(vector<int>{1, 2, 3}) << "\n";
    cout << sizeInfo(7) << "\n";
    cout << sizeInfo(2.5) << "\n";
}

#include <bits/stdc++.h>
using namespace std;

template <class T> concept Number = integral<T> || floating_point<T>;

// 1. constrained template parameter
template <Number T> T twice1(T x) { return x * 2; }
// 2. requires clause
template <class T> requires Number<T> T twice2(T x) { return x * 2; }
// 3. trailing requires clause
template <class T> T twice3(T x) requires Number<T> { return x * 2; }
// 4. abbreviated syntax
auto twice4(Number auto x) { return x * 2; }

// requires-expression with simple, type, compound and nested requirements
template <class T> concept Sized = requires(T c) {
    typename T::value_type;                          // type requirement
    { c.size() } -> convertible_to<size_t>;          // compound requirement
    requires sizeof(typename T::value_type) <= 8;    // nested requirement
};

int main() {
    cout << twice1(21) << " " << twice2(1.5) << " " << twice3(4L) << " " << twice4(10) << "\n";
    cout << boolalpha;
    cout << "Number<int>    = " << Number<int> << "\n";
    cout << "Number<string> = " << Number<string> << "\n";
    cout << "Sized<vector<int>> = " << Sized<vector<int>> << "\n";
    cout << "Sized<int> = " << Sized<int> << "\n";
    cout << "Sized<vector<array<char,100>>> = " << Sized<vector<array<char, 100>>> << "\n";
}

#include <bits/stdc++.h>
using namespace std;

template <class T> concept Integral = is_integral_v<T>;
template <class T> concept SignedIntegral = Integral<T> && is_signed_v<T>;

// Named concepts: SignedIntegral subsumes Integral, so it wins for int
template <Integral T> string pick(T) { return "Integral"; }
template <SignedIntegral T> string pick(T) { return "SignedIntegral (more constrained)"; }

// Raw expressions: each "requires" is a different atom, so no ordering
template <class T> requires is_integral_v<T> string raw(T) { return "A"; }
template <class T> requires (is_integral_v<T> && is_signed_v<T>) string raw(T) { return "B"; }

int main() {
    cout << "pick(5)   : " << pick(5) << "\n";
    cout << "pick(5u)  : " << pick(5u) << "\n";   // unsigned fails SignedIntegral
    cout << "raw(5u)   : " << raw(5u) << "\n";    // only A viable
    // raw(5) is viable for both A and B. The atom is_integral_v<T> inside B is
    // part of a larger parenthesized expression, so B does not subsume A.
    // That call would be ambiguous, so it is left out to keep this compiling.
    cout << "raw(5) is ambiguous: uncomment to see the error\n";
    // cout << raw(5);
}

