template <class T> struct Base {
    int count = 7;
    void hello() { cout << "  Base::hello\n"; }
};

template <class T> struct Derived : Base<T> {
    using Base<T>::count;
    void run() {
        // count;            // error: Base<T> is dependent, not searched
        cout << "  this->count = " << this->count << "\n";  // fix 1: this->
        this->hello();
        cout << "  using count = " << count << "\n";           // fix 2: using below
    }
