template <class C>
void firstElem(const C& c) {
    // value_type is a dependent name: say it is a type
    typename C::value_type first = *c.begin();
    cout << "  first = " << first << "\n";
}

struct Getter {
    template <int N> int get() const { return N * 10; }
};

template <class G>
void callGet(const G& g) {
    // dependent member template: say it is a template
    cout << "  get<3>() = " << g.template get<3>() << "\n";
}

int main() {
    cout << "dependent base:\n";   Derived<int>().run();
    cout << "typename:\n";         firstElem(vector<int>{9, 8});
    cout << "template keyword:\n"; callGet(Getter{});
}

#include <bits/stdc++.h>
using namespace std;

// Non-template core: compiled once, shared by all element types
static long sumBytes(const void* data, size_t count, size_t size,
                     long (*toLong)(const void*)) {
    long total = 0;
    const char* p = static_cast<const char*>(data);
    for (size_t i = 0; i < count; ++i) total += toLong(p + i * size);
    return total;
}

// Thin template wrapper: tiny, inlines away, one instantiation per type
template <class T>
long sumAll(const vector<T>& v) {
    return sumBytes(v.data(), v.size(), sizeof(T),
                    [](const void* p) { return static_cast<long>(*static_cast<const T*>(p)); });
}

// Type erasure at an API boundary: one compiled function for any callable
long applyTwice(const function<long(long)>& f, long x) { return f(f(x)); }

int main() {
    vector<int> a{1, 2, 3};
    vector<short> b{10, 20};
    vector<double> c{1.9, 2.9};
    cout << "sumAll<int>    = " << sumAll(a) << "\n";
    cout << "sumAll<short>  = " << sumAll(b) << "\n";
    cout << "sumAll<double> = " << sumAll(c) << " (truncated per element)\n";
    cout << "applyTwice(+3, 10) = " << applyTwice([](long v) { return v + 3; }, 10) << "\n";
    cout << "applyTwice(*2, 10) = " << applyTwice([](long v) { return v * 2; }, 10) << "\n";
}
